import { useEffect, useId, useRef, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: (code: string) => void;
}

const COPIED_FEEDBACK_MS = 1500;

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const statusId = useId();
  const [copied, setCopied] = useState(false);
  const [failed, setFailed] = useState(false);
  const timerRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    return () => window.clearTimeout(timerRef.current);
  }, []);

  const handleCopy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(code);
      window.clearTimeout(timerRef.current);
      setFailed(false);
      setCopied(true);
      timerRef.current = window.setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
      onCopy(code);
    } catch {
      setCopied(false);
      setFailed(true);
    }
  };

  const statusText = copied ? "Copied to clipboard" : failed ? "Copy failed" : "";

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h3 className="code-card__title" id={titleId}>
          {title}
        </h3>
        <button
          type="button"
          className="code-card__button"
          onClick={handleCopy}
          aria-describedby={statusId}
          data-copied={copied || undefined}
        >
          {copied ? "Copied" : "Copy"}
        </button>
      </header>

      <pre className="code-card__code" tabIndex={0} aria-label={`${title} SQL`}>
        <code>{code}</code>
      </pre>

      <span id={statusId} className="code-card__status" role="status" aria-live="polite">
        {statusText}
      </span>
    </section>
  );
}
