.code-card__button:focus-visible,
.code-card__code:focus-visible {
  outline: 2px solid var(--cc-focus);
  outline-offset: 2px;
}

.code-card__code {
  margin: 0;
  padding: 0.75rem 0.875rem;
  overflow-x: auto;
  background: var(--cc-code-surface);
  border-radius: 8px;
  color: var(--cc-code-text);
  font-family: ui-monospace, "SFMono-Regular", "JetBrains Mono", Menlo, Consolas, monospace;
